import ibex_pyarrow
from ibex_polars import IbexEngine
from ibex_polars._engine import _to_polars
sys.path.insert(0,'/home/brj/code/polars-benchmark');root=Path('/home/brj/code/polars-benchmark/data/tables/scale-10.0')
q=importlib.import_module('queries.polars.q19').q(**{p.stem:pl.scan_parquet(p) for p in root.glob('*.parquet')});e=IbexEngine().prepare(q)
s,t,b,expected,output=e._prepare(q,pl.QueryOptFlags())
filters=re.findall(r'\[filter ([^\]]+)\]',s);assert len(filters)==3
final_at=s.rfind('[select { `revenue`');sum_at=s.rfind('[select { `_ibex_round_aggregate_0`',0,final_at)
compact=s.split('\n',1)[0]+'\n(parquet::read(^_ibex_scalar_0) join parquet::read(^_ibex_scalar_1) on {p_partkey = l_partkey})[filter '+ ' && '.join('('+f+')' for f in filters)+']'+s[sum_at:]
# Retain the alias wrappers while removing only identity projections.
def drop_identity(m):
 fields=m.group(1).split(', ')
 return '' if all((lambda a:len(a)==2 and a[0]==a[1])(f.split(' = ')) for f in fields) else m.group(0)
identity=re.sub(r'\[select \{ ([^{}]+) \}\]',drop_identity,s)
sources={'adapter':s,'drop_identity':identity,'compact':compact}
reference=q.collect(engine='streaming')
calls={n:lambda source=source:_to_polars(ibex_pyarrow.execute_pipeline(source,tables=t,scalars=b),expected,output) for n,source in sources.items()}
calls['polars_streaming']=lambda:q.collect(engine='streaming')
if len(sys.argv)>1 and sys.argv[1]=='profile':
 for n in ('adapter','drop_identity','compact'):
  print('PROFILE',n,flush=True)
  for _ in range(2):assert_frame_equal(calls[n](),reference,rel_tol=1e-10,abs_tol=1e-8)
else:
 for n,c in calls.items():
  for _ in range(2):assert_frame_equal(c(),reference,rel_tol=1e-10,abs_tol=1e-8)
 values={n:[] for n in calls};previous=None
 for i in range(6):
  for n in (list(calls) if i%2==0 else list(reversed(calls))):
   start=time.perf_counter_ns();result=calls[n]();elapsed=(time.perf_counter_ns()-start)/1e6;previous=result
   assert_frame_equal(result,reference,rel_tol=1e-10,abs_tol=1e-8);values[n].append(elapsed)
 report={'threads':os.getenv('IBEX_CORES'),'median_ms':{n:statistics.median(v) for n,v in values.items()},'samples_ms':values,'sources':sources,'bindings':b,'driver':Path(__file__).read_text(),'correctness':'Every complete output matches streaming Polars'}
 Path('/tmp/q19-variants-'+os.getenv('IBEX_CORES')+'.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report['median_ms']),flush=True)
